16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Email;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a leading '+' and 8 to 15 digits)")
50	    private String telephone;
51	
52	    @Column(name = "email")
53	    @Email
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "birth_date")
60	    private LocalDate birthDate;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "household_id")
66	    private String householdId;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "postcode")
72	    private String postcode;
73	
74	    /**
75	     * Write-only, non-persistent acknowledgement that this owner deliberately shares a
76	     * household with an existing owner. When {@code true}, creation is allowed even if
77	     * another owner already has the same lastName and address.
78	     */
79	    @Transient
80	    private boolean sharesHousehold;
81	
82	    /**
83	     * Read-only, non-persistent count of the owners that share this owner's {@code householdId}
84	     * (including this owner), populated by the service when an owner is loaded for presentation.
85	     * Zero when the owner belongs to no household. Used to derive the membership tier.
86	     */
87	    @Transient
88	    private int householdSize;
89	
90	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
91	    private Set<Pet> pets;
92	
93	    public String getAddress() {
94	        return this.address;
95	    }
96	
97	    public void setAddress(String address) {
98	        this.address = address;
99	    }
100	
101	    public String getCity() {
102	        return this.city;
103	    }
104	
105	    public void setCity(String city) {
106	        this.city = city;
107	    }
108	
109	    public String getTelephone() {
110	        return this.telephone;
111	    }
112	
113	    public void setTelephone(String telephone) {
114	        this.telephone = telephone;
115	    }
116	
117	    public String getEmail() {
118	        return this.email;
119	    }
120	
121	    public void setEmail(String email) {
122	        this.email = email;
123	    }
124	
125	    public LocalDate getRegistrationDate() {
126	        return this.registrationDate;
127	    }
128	
129	    public void setRegistrationDate(LocalDate registrationDate) {
130	        this.registrationDate = registrationDate;
131	    }
132	
133	    public LocalDate getBirthDate() {
134	        return this.birthDate;
135	    }
136	
137	    public void setBirthDate(LocalDate birthDate) {
138	        this.birthDate = birthDate;
139	    }
140	
141	    /**
142	     * The owner's age band derived from {@code birthDate} measured against {@code registrationDate}:
143	     * {@code "MINOR"} when under 18, {@code "ADULT"} from 18 to 64, and {@code "SENIOR"} at 65 or
144	     * over. Returns null when either the birth date or the registration date is not set.
145	     */
146	    public String getAgeBand() {
147	        if (this.birthDate == null || this.registrationDate == null) {
148	            return null;
149	        }
150	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
151	        if (age < 18) {
152	            return "MINOR";
153	        }
154	        if (age < 65) {
155	            return "ADULT";
156	        }
157	        return "SENIOR";
158	    }
159	
160	    public String getCustomerCode() {
161	        return this.customerCode;
162	    }
163	
164	    public void setCustomerCode(String customerCode) {
165	        this.customerCode = customerCode;
166	    }
167	
168	    public String getHouseholdId() {
169	        return this.householdId;
170	    }
171	
172	    public void setHouseholdId(String householdId) {
173	        this.householdId = householdId;
174	    }
175	
176	    public Integer getNamesakeCount() {
177	        return this.namesakeCount;
178	    }
179	
180	    public void setNamesakeCount(Integer namesakeCount) {
181	        this.namesakeCount = namesakeCount;
182	    }
183	
184	    public String getPostcode() {
185	        return this.postcode;
186	    }
187	
188	    public void setPostcode(String postcode) {
189	        this.postcode = postcode;
190	    }
191	
192	    /** The highest membership level assignable on creation; level 4 is reserved for tenure. */
193	    public static final int MAX_MEMBERSHIP_LEVEL = 3;
194	
195	    /**
196	     * The owner's numeric membership level, computed from stored fields: it starts at 1, gains 1
197	     * when an email is present, gains 1 when {@code namesakeCount} is 0, and is capped at
198	     * {@value #MAX_MEMBERSHIP_LEVEL} (level 4 is reserved for tenure).
199	     */
200	    public int getMembershipLevel() {
201	        int level = 1;
202	        if (this.email != null && !this.email.isEmpty()) {
203	            level++;
204	        }
205	        if (this.namesakeCount != null && this.namesakeCount == 0) {
206	            level++;
207	        }
208	        return Math.min(level, MAX_MEMBERSHIP_LEVEL);
209	    }
210	
211	    /**
212	     * The derived identity key used to detect duplicate owners: the (already normalized) telephone,
213	     * the email or empty, and the {@code householdId} or empty, joined with {@code '|'}. This single
214	     * key consolidates the former separate telephone, email and household duplicate rules — two
215	     * owners are duplicates only when their whole identity keys are equal. Because the telephone is
216	     * part of the key, two members of the same household (same {@code householdId}) with different
217	     * telephones have different keys and are both allowed.
218	     */
219	    public String getIdentityKey() {
220	        String tel = this.telephone == null ? "" : this.telephone;
221	        String mail = this.email == null ? "" : this.email;
222	        String household = this.householdId == null ? "" : this.householdId;
223	        return tel + "|" + mail + "|" + household;
224	    }
225	
226	    /**
227	     * A single Luhn check digit (0-9) computed over the digits contained in {@code customerCode},
228	     * or null when the {@code customerCode} has not been assigned.
229	     */
230	    public Integer getCheckDigit() {
231	        if (this.customerCode == null) {
232	            return null;
233	        }
234	        int sum = 0;
235	        boolean dbl = true;
236	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
237	            char c = this.customerCode.charAt(i);
238	            if (c < '0' || c > '9') {
239	                continue;
240	            }
241	            int d = c - '0';
242	            if (dbl) {
243	                d *= 2;
244	                if (d > 9) {
245	                    d -= 9;
246	                }
247	            }
248	            sum += d;
249	            dbl = !dbl;
250	        }
251	        return (10 - (sum % 10)) % 10;
252	    }
253	
254	    public boolean isSharesHousehold() {
255	        return this.sharesHousehold;
256	    }
257	
258	    public void setSharesHousehold(boolean sharesHousehold) {
259	        this.sharesHousehold = sharesHousehold;
260	    }
261	
262	    public int getHouseholdSize() {
263	        return this.householdSize;
264	    }
265	
266	    public void setHouseholdSize(int householdSize) {
267	        this.householdSize = householdSize;
268	    }
269	
270	    protected Set<Pet> getPetsInternal() {
271	        if (this.pets == null) {
272	            this.pets = new HashSet<>();
273	        }
274	        return this.pets;
275	    }
276	
277	    protected void setPetsInternal(Set<Pet> pets) {
278	        this.pets = pets;
279	    }
280	
281	    public List<Pet> getPets() {
282	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
283	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
284	        return Collections.unmodifiableList(sortedPets);
285	    }
286	
287	    public void setPets(List<Pet> pets) {
288	        this.pets = new HashSet<>(pets);
289	    }
290	
291	    public void addPet(Pet pet) {
292	        getPetsInternal().add(pet);
293	        pet.setOwner(this);
294	    }
295	
296	    /**
297	     * Return the Pet with the given name, or null if none found for this Owner.
298	     *
299	     * @param name to test
300	     * @return true if pet name is already in use
301	     */
302	    public Pet getPet(String name) {
303	        return getPet(name, false);
304	    }
305	
306	    /**
307	     * Return the Pet with the given name, or null if none found for this Owner.
308	     *
309	     * @param name to test
310	     * @return true if pet name is already in use
311	     */
312	    public Pet getPet(String name, boolean ignoreNew) {
313	        name = name.toLowerCase();
314	        for (Pet pet : getPetsInternal()) {
315	            if (!ignoreNew || !pet.isNew()) {
316	                String compName = pet.getName();
317	                compName = compName.toLowerCase();
318	                if (compName.equals(name)) {
319	                    return pet;
320	                }
321	            }
322	        }
323	        return null;
324	    }
325	
326	    public Pet getPet(Integer petId) {
327	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
328	    }
329	
330	    @Override
331	    public String toString() {
332	        return new ToStringCreator(this)
333	
334	            .append("id", this.getId())
335	            .append("new", this.isNew())
336	            .append("lastName", this.getLastName())
337	            .append("firstName", this.getFirstName())
338	            .append("address", this.address)
339	            .append("city", this.city)
340	            .append("telephone", this.telephone)
341	            .toString();
342	    }
343	}
